import { Component, inject, computed } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { AutorizacionesListComponent } from '../../../shared/components/autorizaciones-list/autorizaciones-list.component';

const STATUS_PRESET_MAP: Record<string, string[]> = {
  'recibidas': ['Enviada'],
  'subsanadas': ['Subsanada'],
  'no-completadas': ['Incompleta', 'No Presentada'],
  'autorizadas': ['Autorizada'],
  'no-autorizadas': ['No Autorizada'],
  'en-dictaminacion': ['En Dictaminación'],
  'aprobadas': ['Aprobada'],
};

const TITLE_MAP: Record<string, string> = {
  'recibidas': 'Recibidas',
  'subsanadas': 'Subsanadas',
  'no-completadas': 'No completadas',
  'autorizadas': 'Autorizadas',
  'no-autorizadas': 'No Autorizadas',
  'en-dictaminacion': 'En dictaminación',
  'aprobadas': 'Aprobadas',
};

@Component({
  selector: 'app-ejecutivos-bandeja',
  imports: [AutorizacionesListComponent],
  templateUrl: './bandeja.component.html',
})
export class BandejaComponent {
  private readonly route = inject(ActivatedRoute);

  readonly presetKey = this.route.snapshot.data?.['statusPreset'] ?? 'recibidas';

  readonly presetStatuses = computed(() => STATUS_PRESET_MAP[this.presetKey] ?? []);

  readonly presetTitle = computed(() => TITLE_MAP[this.presetKey] ?? 'Bandeja');
}
